#!/usr/bin/env python3
from pathlib import Path
import numpy as np,pandas as pd,json
root=Path(__file__).resolve().parents[1];w=root/'work';o=root/'outputs';z=np.load(w/'stage6_foxp2_1000g_eur_genotypes.npz');ids=z['rsid'];g=z['dosage'].astype(np.float64);d=pd.read_csv(o/'stage6_foxp2_mvp_hfrs_exact_aligned.csv.gz').set_index('rs').loc[ids].copy();af=g.mean(axis=1)/2;d['reference_eur_anchor_af']=af;d['hfrs_anchor_af']=np.where(d.ea_f==d.anchor_effect_allele,d.effect_allele_frequency_f,1-d.effect_allele_frequency_f);d['mvp_anchor_af']=d.effect_allele_frequency_m;d['max_ref_af_disagreement']=np.maximum(abs(af-d.hfrs_anchor_af),abs(af-d.mvp_anchor_af));d['excluded_af_disagreement']=d.max_ref_af_disagreement>.2;d.reset_index().to_csv(o/'stage6_foxp2_allele_frequency_qc.csv',index=False); keep=~d.excluded_af_disagreement.to_numpy();g=g[keep];d=d.loc[keep];assert len(g)==len(d);(g.astype('<f8')).tofile(w/'stage6_foxp2_reference_genotypes_float64.bin');d.reset_index().to_csv(w/'stage6_foxp2_susie_aligned.csv',index=False);r={'before':len(ids),'after':len(d),'excluded':int(sum(~keep)),'threshold':0.2,'note':'conservative sample-reference frequency discrepancy filter, not proof of strand error'};(o/'stage6_foxp2_frequency_qc_receipt.json').write_text(json.dumps(r,indent=2)+'\n');print(json.dumps(r))
